    public enum Kind {
        Floor, FloorTall, Wall
    }

    private final String Name;
    private final Kind Type;
    private final int Glow;
    private final double[][] Lower;
    private final double[][] Upper;

    Scp5001HabCatalog(String Name, Kind Type, int Glow, double[][] Lower, double[][] Upper) {
        this.Name = Name;
        this.Type = Type;
        this.Glow = Glow;
        this.Lower = Lower;
        this.Upper = Upper;
    }

    public String id() {
        return Name;
    }

    public Kind kind() {
        return Type;
    }

    public int glow() {
        return Glow;
    }

    public double[][] lower() {
        return Lower;
    }

    public double[][] upper() {
        return Upper;
    }
